+		LoadKAppUncachedCalled: func(address []byte) (state.KAppAccountHandler, error) {
+			return state.NewKAppAccount(address)
+		},
+	}))
+
+	done := make(chan struct{})
+	go func() {
+		defer close(done)
+		for i := 0; i < 500; i++ {
+			_ = sharedApp.SetStorage([]byte(fmt.Sprintf("key-%d", i)), []byte("meta"))
+		}
